styles.add(ParagraphStyle(name="White", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=8, textColor=colors.white))

def P(text, style="BodyGuide"):
    return Paragraph(text, styles[style])

def code(value):
    return Preformatted(json.dumps(value, indent=2), styles["CodeGuide"])

def method_label(method, path):
    palette = {"GET": teal, "POST": green, "PATCH": orange, "PUT": purple, "DELETE": colors.HexColor("#B42318")}
    return Table([[P(method, "White"), P(path, "White")]], colWidths=[20*mm, 155*mm], style=TableStyle([("BACKGROUND", (0,0), (0,0), palette[method]), ("BACKGROUND", (1,0), (1,0), blue), ("VALIGN", (0,0), (-1,-1), "MIDDLE"), ("LEFTPADDING", (0,0), (-1,-1), 7), ("RIGHTPADDING", (0,0), (-1,-1), 7), ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6)]))

def endpoint(method, path, purpose, request=None, response=None, notes=None):
    flow = [method_label(method, path), P("<b>Purpose:</b> " + purpose)]
    if request is not None:
        flow += [P("<b>Request JSON</b>"), code(request)]
    if response is not None:
        flow += [P("<b>Response JSON</b>"), code(response)]
    if notes:
        flow += [P("<b>Frontend notes:</b> " + notes)]
    flow.append(Spacer(1, 6))
    return flow

story = [Spacer(1, 10*mm), Paragraph("FarmOS Frontend API Integration Guide", styles["TitleBrand"]), Paragraph("Domain 01 governance and approved Domain 02 contracts  |  API v2.2", styles["Sub"]), P("Scope: this guide covers the locked Domain 01 correction and the implemented Domain 02 contracts: D02-COR-001, D02-002 through D02-010, plus the accepted implemented foundations for D02-011 through D02-014. It is an integration guide and does not replace fuller domain-specific API references."), P("Backend authorization remains authoritative; the frontend must not infer permission from role names."), Spacer(1, 6), Paragraph("1. Integration sequence", styles["H1Brand"]), P("Follow this order after the user opens the application:"), P("1. Send the channel header. 2. Log in. 3. Store cookies automatically. 4. Fetch the current user profile. 5. Fetch capabilities and navigation. 6. Render only permitted governance screens. 7. Call organization/farm endpoints with authorized identifiers. 8. Handle structured error codes."), Paragraph("Required headers", styles["H2Brand"]), code({"Content-Type": "application/json", "X-App-Channel": "web", "X-CSRFToken": "value-from-client_csrf_token"}), P("Use X-App-Channel: mobile for the mobile client. Do not store access or refresh tokens in browser localStorage; the backend uses secure cookies."), Paragraph("2. Standard response envelopes", styles["H1Brand"]), P("Every v2 endpoint returns a predictable JSON envelope. Read data from data and pagination information from meta."), code({"success": True, "code": "REQUEST_SUCCESSFUL", "message": "Request completed successfully.", "data": {"id": 123}, "meta": None}), code({"success": False, "code": "PERMISSION_DENIED", "message": "You do not have permission to perform this action.", "data": None, "errors": {}, "retryable": False}), PageBreak()]

story += [Paragraph("3. Authentication and bootstrap", styles["H1Brand"])]
