story += endpoint("POST", "/api/v2/operations/tasks/", "Create planned work. Typed titles are derived by the backend; generic tasks require a meaningful title.", {"farm_id": 1, "task_type": "vaccination", "animal_id": 42, "assignee_id": "uuid", "due_at": "2026-09-24T09:00:00+01:00", "priority": "high", "description": "Use cattle crush near Pen 3."}, {"success": True, "data": {"task_type": "vaccination", "title": "Vaccinate ANIMAL-042", "status": "assigned"}}, "Canonical types: vaccination, treatment, feed_issuance, observation, weight, movement, pregnancy_check, sale, mortality, and generic. Treatment, observation, weight, pregnancy check, sale, and mortality require an individual animal; pregnancy check requires a female animal. Vaccination, feed issuance, and movement accept either an animal or group. generic may be farm-scoped without a subject.")
story += [Paragraph("11. Scheduling and recurring work (D02-007)", styles["H1Brand"]), P("A Schedule is a farm-scoped reusable work-generation rule, not a Task. Its state is active/inactive; every run creates a normal independently traceable Operations Task with source.type=schedule and source.id set to the schedule ID. Deactivating a schedule stops future generation only; it does not cancel or rewrite prior tasks."),
    *endpoint("POST", "/api/v2/operations/schedules/", "Create an active farm-scoped schedule. Set run_now true only when the user understands it generates a Task immediately and advances the schedule.", {"farm_id": 1, "task_type": "vaccination", "title": "Monthly CBPP round", "animal_id": 42, "recurrence": "monthly", "next_run_at": "2026-10-01T07:00:00+01:00", "assignee_id": "uuid", "run_now": False}, {"success": True, "data": {"id": 17, "task_type": "vaccination", "title": "Monthly CBPP round", "recurrence": "monthly", "next_run_at": "2026-10-01T07:00:00+01:00", "is_active": True}} , "Allowed recurrence values are once, daily, weekly, and monthly. The server validates the subject and assignee with the same farm/access rules as generated Tasks. Schedule title is explicit and is retained by generated tasks."),
    *endpoint("POST", "/api/v2/operations/schedules/{schedule_id}/run/", "Manually generate the current occurrence from an existing schedule.", response={"success": True, "data": {"id": 304, "title": "Monthly CBPP round", "status": "assigned", "source": {"type": "schedule", "id": 17}}}, notes="Manual Run remains schedule-sourced while the triggering user is retained as the task/event actor. It advances next_run_at; for once it deactivates the schedule. Confirm this consequence in the UI."),
    *endpoint("PATCH", "/api/v2/operations/schedules/{schedule_id}/", "Update supported future-template fields, including title, description, recurrence, next_run_at, subject, assignee, and is_active.", {"is_active": True}, notes="Edits apply only to future generation and never rewrite historical tasks or results. Do not offer unsupported custom cron, weekday, or biweekly controls."),
    *endpoint("POST", "/api/v2/operations/schedules/{schedule_id}/deactivate/", "Deactivate future execution while preserving schedule/task history.", response={"success": True, "data": {"id": 17, "is_active": False}}, notes="Use deactivation rather than hard delete. GET /api/v2/operations/schedules/ and GET /api/v2/operations/schedules/{schedule_id}/ are farm-scoped reads."),
    P("next_run_at is backend-authoritative and recurrence is calculated in Africa/Lagos time. Display the returned offset-aware timestamp; do not calculate recurrence in the frontend. Automatic generation is server controlled and occurrence-idempotent. A monthly recurrence uses the last valid day where a calendar date does not exist (for example, January 31 advances to February 28/29). On reactivation, the backend creates one missed occurrence then advances to the next future occurrence; it does not backfill every missed interval. If a stored assignee is no longer eligible, the backend deactivates the schedule without generating unauthorized work.")]

story += [Paragraph("12. My Work and field execution (D02-008)", styles["H1Brand"]), P("My Work is the signed-in user's server-scoped personal execution inbox. Use GET /api/v2/operations/my-work/ for paginated open tasks assigned to that user, and GET /api/v2/dashboard/my-work/ for the backend-authoritative Open, Overdue, Completed Today, Today, Overdue and Upcoming summary. Never construct My Work by downloading a farm-wide task list and filtering it in the client."), *endpoint("GET", "/api/v2/operations/my-work/?farm_id=1", "Fetch only the current user's open assigned tasks in an authorized farm.", response={"success": True, "data": [{"id": 304, "title": "Vaccinate COW-001", "subject": {"type": "animal", "id": 42, "label": "COW-001"}, "status": "assigned", "is_overdue": False}], "meta": {"pagination": {"page": 1}}}, notes="farm_id narrows access only. Subject, priority, due_at and lifecycle status are distinct data dimensions."), P("Use GET /api/v2/users/me/tasks/ for the personal All Tasks/history view, with optional status and farm_id filters. Use GET /api/v2/users/me/activity/ for the authenticated user's activity timeline, optionally narrowed by farm_id. Both are server-scoped and must not be replaced with client-side aggregation."), P("Task actions remain contextual: Accept acknowledges work; Start is optional; Complete uses the task-type-specific domain form and authoritative backend transaction; Unable to Complete sends a canonical reason code. Cancel requires cancel_operation and is not granted merely by assignment. Supported retries must reuse the same client_request_id. Completed tasks leave the open inbox."), P("My Work is user-centric rather than role-name-centric, but channel entitlement remains enforced. It is personal work, not a manager operations workspace or Quick Record path. Offline mobile records remain pending until backend revalidation succeeds; show sync/conflict state rather than claiming final completion locally.")]
