story += [Paragraph("15. Farm and historical-data isolation (D02-010)", styles["H1Brand"]), P("D02-010 is product locked. A direct object outside the current authorized Organization/Farm/data scope is concealed as 404 NOT_FOUND; do not reveal its existence. Return 403 PERMISSION_DENIED only when the object is within the user's visible Farm scope but the requested action is not permitted."), P("On the next successful mobile synchronization, call GET /mobile/api/sync-scope/ and remove operational cache data belonging only to Farm IDs absent from authorized_farm_ids. Cached data is never authoritative; queued writes are reauthorized by the server and can be rejected after access revocation."), P("Farm deactivation preserves identity and operational history. Do not offer hard deletion for a Farm with historical Tasks, results, events, schedules, or assignments. After an Animal moves Farm, historical records retain their original Farm scope; a Farm B-only user cannot access Farm A history, while dual-Farm and Organization-wide users may access their authorized history."), *endpoint("GET", "/mobile/api/sync-scope/", "Fetch the authoritative current Farm scope before reconciling offline operational cache.", response={"success": True, "data": {"authorized_farm_ids": [1, 3], "cache_policy": "remove_revoked_farm_operational_data"}}, notes="Remove cached operational records exclusively belonging to Farm IDs not returned. This endpoint may be called with a live mobile session after Farm access has been revoked so the client can safely reconcile local state."), Paragraph("16. Events, audit and activity (D02-011)", styles["H1Brand"]), P("Material Operations actions create immutable, structured canonical events. The frontend must treat the returned current Task state as current state only; event history is the authority for how that state was reached."), P("Web clients continue using the secure-cookie flow. Mobile clients continue using JWT Bearer tokens only under /mobile/api/."), Paragraph("17. Notifications and alerts (D02-012)", styles["H1Brand"]), P("Use GET /api/v2/notifications/ for the authenticated recipient's Notification Center and GET /api/v2/notifications/unread-count/ for its matching badge. Mark only the signed-in recipient's records read through POST /api/v2/notifications/{notification_id}/read/ or /read-all/. Use notification_type and the authoritative reference, not title/body text; opening the reference rechecks current authorization."), P("Alerts are condition projections, not Task statuses or notification substitutes. Existing farm/health alert and Operations exception resources remain the authoritative attention views. No due-soon threshold, escalation, severity, external delivery, SMS, WhatsApp, or blanket completion notification policy is implied."), Paragraph("18. Error handling and retry behavior", styles["H1Brand"]), code({"success": False, "code": "FARM_NOT_FOUND", "message": "Farm could not be found.", "data": None, "errors": {}, "retryable": False}), P("Handle codes, not message text. Recommended frontend actions:"), P("AUTHENTICATION_REQUIRED / SESSION_EXPIRED → refresh once or redirect to login. ACCOUNT_DEACTIVATED → sign out and show account notice. FARM_NOT_FOUND for an inaccessible scope → show a neutral unavailable state without implying that the object exists. PERMISSION_DENIED / CHANNEL_ACCESS_DENIED → show access-denied state. VALIDATION_ERROR → show field errors. CONFLICT → preserve the server result or ask the user to resolve the conflict."), Paragraph("19. Implementation evidence", styles["H1Brand"]), P("Implementation evidence is maintained under api_dev/reports/evidence/."), Paragraph("20. Implementation checklist", styles["H1Brand"]), P("✓ Send X-App-Channel. ✓ Use secure cookies. ✓ Use capability booleans. ✓ Read the standard envelope. ✓ Never allow frontend-only tenant filtering."), Spacer(1, 8), P("Contract reference: FarmOS Frontend API Contract v2.2, including implemented D02-007 through D02-010 and accepted foundations for D02-011 through D02-014. Backend base URL for Docker development: http://127.0.0.1:8082.")]

